  f[at + 6] = o.A;
  f[at + 7] = o.B;
  f[at + 8] = o.Q;
  f[at + 9] = o.waveCountdown;
  f[at + 10] = o.wave;
  f[at + 11] = o.stagger;
  f[at + 12] = o.released;
  f[at + 13] = o.localsCap;
