// The first mirrored field of `m` that is not what the export row says (a
// write JavaScript made to Rust's state without a command), or null.
export function checkSpawning(b, f, at, h, m) {
  const want = syncSpawning(b, f, at, h, new SpawningMirror());
  if (!Object.is(m.heroes, want.heroes)) return ".heroes";
  if (!Object.is(m.demo, want.demo)) return ".demo";
  if (!sameEach(m.teams, want.teams, (x, y) => sameSpawnTeam(x, y) === null)) return ".teams";
  if (!Object.is(m.A, want.A)) return ".A";
  if (!Object.is(m.B, want.B)) return ".B";
  if (!Object.is(m.Q, want.Q)) return ".Q";
  if (!Object.is(m.waveCountdown, want.waveCountdown)) return ".waveCountdown";
  if (!Object.is(m.wave, want.wave)) return ".wave";
  if (!Object.is(m.stagger, want.stagger)) return ".stagger";
  if (!Object.is(m.released, want.released)) return ".released";
  if (!Object.is(m.localsCap, want.localsCap)) return ".localsCap";
  if (!sameEach(m.characters, want.characters, (x, y) => Object.is(x, y))) return ".characters";
  if (!sameMap(m.queues, want.queues, (x, y) => sameArray(x, y, 4))) return ".queues";
  if (!Object.is(m.started, want.started)) return ".started";
  return null;
}

export function sameSpawning(a, b) {
  if (!Object.is(a.heroes, b.heroes)) return ".heroes";
  if (!Object.is(a.demo, b.demo)) return ".demo";
  if (!sameEach(a.teams, b.teams, (x, y) => sameSpawnTeam(x, y) === null)) return ".teams";
  if (!Object.is(a.A, b.A)) return ".A";
  if (!Object.is(a.B, b.B)) return ".B";
  if (!Object.is(a.Q, b.Q)) return ".Q";
  if (!Object.is(a.waveCountdown, b.waveCountdown)) return ".waveCountdown";
  if (!Object.is(a.wave, b.wave)) return ".wave";
  if (!Object.is(a.stagger, b.stagger)) return ".stagger";
  if (!Object.is(a.released, b.released)) return ".released";
  if (!Object.is(a.localsCap, b.localsCap)) return ".localsCap";
  if (!sameEach(a.characters, b.characters, (x, y) => Object.is(x, y))) return ".characters";
  if (!sameMap(a.queues, b.queues, (x, y) => sameArray(x, y, 4))) return ".queues";
  if (!Object.is(a.started, b.started)) return ".started";
  return null;
}

export function exportSpawning(o, cx) {
  let v = cx.seen.get(o);
  if (v) return v;
  v = {};
  cx.seen.set(o, v);
  v.heroes = o.heroes;
  v.demo = o.demo;
  v.teams = o.teams.map((x) => exportSpawnTeam(x, cx));
  v.A = o.A;
  v.B = o.B;
  v.Q = o.Q;
  v.waveCountdown = o.waveCountdown;
  v.wave = o.wave;
  v.stagger = o.stagger;
  v.released = o.released;
  v.localsCap = o.localsCap;
  v.characters = o.characters.map((x) => cx.ref("character", x));
  v.queues = new Map([...o.queues].map(([k, x]) => [exportSpawnPost(k, cx), [...x]]));
  v.started = o.started;
  return v;
}
